    get(args: { workspace: string }): Promise<AppAgentIdentity>
    /** Change the room's agent's name, color or picture. cap agent:identity · POST /cli/agent/identity. e.g. `await k2.agentIdentity.set({workspace, color: '#3366ff'})` */
